mkdir -p ~/academy-labs/g8-2 && cd ~/academy-labs/g8-2
cat > plan.json <<'EOF'
{
  "ticket": "RH-1234",
  "done": "A workgroup with no projects shows a \"No projects yet\" card instead of an empty grid.",
  "checks": [
    { "id": "C1", "what": "empty workgroup shows the No projects yet card", "proof": "screenshots" },
    { "id": "C2", "what": "a filter with no match shows No results, not the empty card", "proof": "video" },
    { "id": "C3", "what": "1,000 projects: the first page shows 25 rows", "proof": "text" }
  ]
}
EOF

cat > trace.mjs <<'EOF'
// Follows each check of the plan into the PR body: right headings, and one line per check with a result and its proof.
import { readFileSync } from "node:fs";

const [planFile, prFile] = process.argv.slice(2);
const plan = JSON.parse(readFileSync(planFile, "utf8"));
const pr = readFileSync(prFile, "utf8");

const HEADINGS = ["What changes", "Why", "How it was checked", "What was not checked, and why", "Risk and rollback", "Where to look first"];
const PROOF = {
  screenshots: (l) => /760/.test(l) && /1440/.test(l),
  video: (l) => /\.(mp4|webm|mov)\b|\bvideo\b/i.test(l),
  text: (l) => /`[^`]+`/.test(l),
};

const found = [...pr.matchAll(/^## (.+)$/gm)].map((m) => m[1].trim());
const inOrder = HEADINGS.every((h, i) => found[i] === h);
console.log(inOrder ? "✔ headings in the fixed order" : `✘ headings\n   want: ${HEADINGS.join(" / ")}\n   have: ${found.join(" / ")}`);

const checked = (pr.split(/^## How it was checked\s*$/m)[1] ?? "").split(/^## /m)[0].split("\n");
let bad = inOrder ? 0 : 1;
for (const c of plan.checks) {
  const line = checked.find((l) => l.includes(c.id));
  const problem = !line ? "no line in How it was checked"
    : !/\b(pass|fail)\b/i.test(line) ? "no pass or fail"
    : !PROOF[c.proof](line) ? `the plan asked for ${c.proof} as proof`
    : null;
  if (problem) bad++;
  console.log(`${problem ? "✘" : "✔"} ${c.id} ${c.what}${problem ? `: ${problem}` : ""}`);
}
console.log(bad ? `\n${bad} problem(s): a reviewer cannot trace every check to its proof` : "\nEvery check in the plan has a result and the proof it promised");
process.exit(bad ? 1 : 0);
EOF
